function initPublicOutageCategoryOrder(){const active=activeCategories();const saved=Array.isArray(db.settings.publicOutageCategoryOrder)?db.settings.publicOutageCategoryOrder:[];publicOutageCategoryOrderDraft=[...saved.filter(x=>active.includes(x)),...active.filter(x=>!saved.includes(x))]}
function renderPublicOutageCategoryOrder(){const host=$('#publicOutageCategoryOrderManager');if(!host)return;if(!publicOutageCategoryOrderDraft.length)initPublicOutageCategoryOrder();const draw=()=>{host.innerHTML=publicOutageCategoryOrderDraft.map((cat,i)=>`<div class="category-row"><span class="category-order">${i+1}</span><span class="category-name">${esc(cat)}</span><div class="category-actions"><button class="btn ghost small" type="button" data-po-up="${i}" ${i===0?'disabled':''}>↑</button><button class="btn ghost small" type="button" data-po-down="${i}" ${i===publicOutageCategoryOrderDraft.length-1?'disabled':''}>↓</button></div></div>`).join('');$$('[data-po-up]',host).forEach(b=>b.onclick=()=>{const i=Number(b.dataset.poUp);[publicOutageCategoryOrderDraft[i-1],publicOutageCategoryOrderDraft[i]]=[publicOutageCategoryOrderDraft[i],publicOutageCategoryOrderDraft[i-1]];draw()});$$('[data-po-down]',host).forEach(b=>b.onclick=()=>{const i=Number(b.dataset.poDown);[publicOutageCategoryOrderDraft[i],publicOutageCategoryOrderDraft[i+1]]=[publicOutageCategoryOrderDraft[i+1],publicOutageCategoryOrderDraft[i]];draw()})};draw()}
