function delegatedAdminManagerHtml(){return `<section class="card span-12 collapsible-card"><details id="delegatedAdminDetails"><summary><span>Beheerfuncties per medewerker</span><span class="collapse-hint">Openen/sluiten</span></summary><div class="collapsible-content"><p class="sub">Geef individuele Facilitair- of Conciërge-accounts toegang tot specifieke onderdelen van de beheerpagina. Alleen de hoofdbeheerder kan deze rechten toekennen.</p><div id="delegatedAdminManager"></div></div></details></section>`}
